# Fix the component counting to handle multiple colors

def count_components_color(grid, color):
    h, w = len(grid), len(grid[0])
    visited = [[False]*w for _ in range(h)]
    components = 0

    for i in range(h):
        for j in range(w):
            if grid[i][j] == color and not visited[i][j]:
                # BFS
                q = [(i,j)]
                visited[i][j] = True
                while q:
                    r, c = q.pop(0)
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = r+dr, c+dc
                        if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == color and not visited[nr][nc]:
                            visited[nr][nc] = True
                            q.append((nr,nc))
                components += 1

    return components

def count_components_any(grid):
    h, w = len(grid), len(grid[0])
    non_zero_colors = set()
    for i in range(h):
        for j in range(w):
            if grid[i][j] != 0:
                non_zero_colors.add(grid[i][j])

    components = []
    for color in non_zero_colors:
        count = count_components_color(grid, color)
        components.append((color, count))

    return components

